/**
 * knowledge.js — the Knowledge application.
 *
 * Repository-driven: reads the compiled archive at
 * ../../assets/data/knowledge-index.json (generated by
 * tools/build-knowledge.js from the Markdown sources in knowledge/).
 *
 * Views (hash-routed):
 *   #/                 home (hero, search, domains, recents, recently acquired)
 *   #/all              all knowledge
 *   #/domains          domain grid
 *   #/domain/:slug     entries in a domain
 *   #/topics           entries grouped by conceptual type
 *   #/tools            tools
 *   #/tag/:tag         entries with a tag
 *   #/entry/:slug      single entry (reader)
 *
 * Global UX: Ctrl/Cmd+K command palette, wiki-link hover previews,
 * copy buttons, reading mode, reduced-motion support.
 */

import { renderMarkdown, escapeHtml, slugify } from './md.js';

'use strict';

// ---------------------------------------------------------------------------
// State
// ---------------------------------------------------------------------------
const state = {
  entries: [],
  bySlug: new Map(),
  searchIndex: [],
  loaded: false,
  loadError: null,
  readingPref: false,
};

const RECENTS_KEY = 'knowledge.recents.v1';
const READING_KEY = 'knowledge.reading.v1';

const $ = (sel, root = document) => root.querySelector(sel);

const esc = (v) => escapeHtml(v == null ? '' : v);

const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];

function fmtDate(ms) {
  if (!ms) return '';
  const d = new Date(ms);
  const day = String(d.getDate()).padStart(2, '0');
  return `${day} ${MONTHS[d.getMonth()]} ${d.getFullYear()}`;
}

function prefersReducedMotion() {
  return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
}

// ---------------------------------------------------------------------------
// Loading
// ---------------------------------------------------------------------------
function normalizeEntry(raw) {
  return {
    slug: String(raw.slug || ''),
    title: String(raw.title || 'Untitled'),
    type: String(raw.type || 'concept').toLowerCase(),
    domain: String(raw.domain || 'General'),
    tags: Array.isArray(raw.tags) ? raw.tags.map(String) : [],
    related: Array.isArray(raw.related) ? raw.related.map(String) : [],
    wikilinks: Array.isArray(raw.wikilinks) ? raw.wikilinks.map(String) : [],
    file: raw.file || '',
    dateAdded: raw.dateAdded || null,
    dateModified: raw.dateModified || null,
    excerpt: raw.excerpt || '',
    body: raw.body || '',
  };
}

async function loadIndex() {
  try {
    const res = await fetch('../../assets/data/knowledge-index.json', { cache: 'no-store' });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json();
    state.entries = (data.entries || []).map(normalizeEntry);
    state.bySlug = new Map(state.entries.map((e) => [e.slug, e]));
    state.searchIndex = buildSearchIndex(state.entries);
    state.loaded = true;
  } catch (err) {
    state.loadError = err;
  }
  renderRoute();
}

// ---------------------------------------------------------------------------
// Recents (localStorage)
// ---------------------------------------------------------------------------
function getRecents() {
  try {
    const v = JSON.parse(localStorage.getItem(RECENTS_KEY) || '[]');
    return Array.isArray(v) ? v : [];
  } catch {
    return [];
  }
}

function addRecent(slug) {
  const recents = getRecents().filter((s) => s !== slug);
  recents.unshift(slug);
  localStorage.setItem(RECENTS_KEY, JSON.stringify(recents.slice(0, 8)));
}

// ---------------------------------------------------------------------------
// Search
// ---------------------------------------------------------------------------
function buildSearchIndex(entries) {
  return entries.map((e) => ({
    e,
    hay: [e.title, e.domain, e.type, e.tags.join(' '), e.body].join('\n').toLowerCase(),
  }));
}

function runSearch(q) {
  const tokens = q.toLowerCase().split(/\s+/).filter(Boolean);
  if (!tokens.length) return [];
  const scored = [];
  for (const { e, hay } of state.searchIndex) {
    let score = 0;
    for (const t of tokens) {
      const titleLow = e.title.toLowerCase();
      if (titleLow === t) score += 120;
      else if (titleLow.startsWith(t)) score += 90;
      else if (titleLow.includes(t)) score += 60;
      if (e.tags.some((tag) => { const tl = tag.toLowerCase(); return tl === t || tl.startsWith(t); })) score += 45;
      if (e.domain.toLowerCase() === t || e.type.toLowerCase() === t) score += 40;
      if (hay.includes(t)) score += 10;
    }
    if (score > 0) scored.push({ e, score });
  }
  scored.sort((a, b) => b.score - a.score || a.e.title.localeCompare(b.e.title));
  return scored.slice(0, 30).map((s) => s.e);
}

function highlightTokens(text, tokens) {
  let out = esc(text);
  const sorted = [...tokens].sort((a, b) => b.length - a.length);
  for (const t of sorted) {
    if (!t) continue;
    const re = new RegExp('(' + t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + ')', 'gi');
    out = out.replace(re, '<mark>$1</mark>');
  }
  return out;
}

function makeSnippet(entry, q) {
  const tokens = q.toLowerCase().split(/\s+/).filter(Boolean);
  const body = entry.body || '';
  let idx = -1;
  for (const t of tokens) {
    const i = body.toLowerCase().indexOf(t);
    if (i !== -1 && (idx === -1 || i < idx)) idx = i;
  }
  if (idx === -1) return esc(entry.excerpt || '');
  const start = Math.max(0, idx - 45);
  const end = Math.min(body.length, idx + 110);
  const snip = (start > 0 ? '…' : '') + body.slice(start, end).replace(/\s+/g, ' ') + (end < body.length ? '…' : '');
  return highlightTokens(snip, tokens);
}

// ---------------------------------------------------------------------------
// Router
// ---------------------------------------------------------------------------
function parseRoute() {
  const h = location.hash.replace(/^#\/?/, '');
  const [pathPart, anchor] = h.split('#');
  const parts = pathPart.split('/').filter(Boolean);
  let route;
  if (!parts.length) route = { name: 'home' };
  else {
    switch (parts[0]) {
      case 'entry': route = { name: 'entry', slug: decodeURIComponent(parts[1] || '') }; break;
      case 'domain': route = { name: 'domain', slug: decodeURIComponent(parts[1] || '') }; break;
      case 'tag': route = { name: 'tag', tag: decodeURIComponent(parts[1] || '') }; break;
      case 'all': route = { name: 'all' }; break;
      case 'domains': route = { name: 'domains' }; break;
      case 'topics': route = { name: 'topics' }; break;
      case 'tools': route = { name: 'tools' }; break;
      default: route = { name: 'home' };
    }
  }
  if (anchor) route.anchor = decodeURIComponent(anchor);
  return route;
}

// ---------------------------------------------------------------------------
// Shared view pieces
// ---------------------------------------------------------------------------
function badgeHtml(type) {
  return `<span class="badge badge-${esc(type)}">${esc(type)}</span>`;
}

function entryItemHtml(e) {
  return (
    `<a class="entry-item" href="#/entry/${esc(e.slug)}">` +
    `<div class="entry-item-head">${badgeHtml(e.type)}<span class="entry-item-title">${esc(e.title)}</span></div>` +
    `<div class="entry-item-meta"><span class="entry-item-domain">${esc(e.domain)}</span></div>` +
    `<p class="entry-item-excerpt">${esc(e.excerpt || '')}</p>` +
    `</a>`
  );
}

function domainEntries() {
  const map = new Map();
  for (const e of state.entries) {
    const key = slugify(e.domain) || 'general';
    if (!map.has(key)) map.set(key, { name: e.domain, key, entries: [] });
    map.get(key).entries.push(e);
  }
  return [...map.values()].sort((a, b) => b.entries.length - a.entries.length || a.name.localeCompare(b.name));
}

function domainCardHtml(d, index) {
  const tagCounts = new Map();
  for (const e of d.entries) for (const t of e.tags) tagCounts.set(t, (tagCounts.get(t) || 0) + 1);
  const desc = [...tagCounts.entries()].sort((a, b) => b[1] - a[1]).slice(0, 3).map(([t]) => t).join(' · ');
  const count = d.entries.length;
  return (
    `<a class="domain-card" href="#/domain/${esc(d.key)}">` +
    `<span class="domain-num">${String(index + 1).padStart(2, '0')}</span>` +
    `<h3 class="domain-name">${esc(d.name)}</h3>` +
    `<p class="domain-desc">${desc ? esc(desc) : '&nbsp;'}</p>` +
    `<span class="domain-count">${count} ${count === 1 ? 'entry' : 'entries'}</span>` +
    `</a>`
  );
}

function sectionHeadHtml(title) {
  return `<div class="section-head"><h2>${esc(title)}</h2><span class="section-rule" aria-hidden="true"></span></div>`;
}

// ---------------------------------------------------------------------------
// Views
// ---------------------------------------------------------------------------
function viewHome() {
  const entries = state.entries;
  let parts = [];

  // hero + search
  parts.push(
    `<section class="hero">` +
    `<p class="hero-eyebrow">Personal Cybersecurity Intelligence Archive</p>` +
    `<h1>KNOWLEDGE</h1>` +
    `<p class="hero-tag">Everything worth remembering.</p>` +
    `</section>`
  );

  parts.push(
    `<button type="button" class="home-search" id="home-search" aria-haspopup="dialog">` +
    `<span class="home-search-icon" aria-hidden="true">⌕</span>` +
    `<span class="home-search-text">Search the archive — titles, tools, event IDs, commands…</span>` +
    `<kbd>Ctrl K</kbd>` +
    `</button>`
  );

  if (!entries.length) {
    parts.push(emptyStateHtml());
  } else {
    // explore — domains
    const domains = domainEntries();
    parts.push(`<section class="home-section">${sectionHeadHtml('Explore')}`);
    parts.push(`<div class="domain-grid">${domains.map((d, i) => domainCardHtml(d, i)).join('')}</div>`);
    parts.push(`</section>`);

    // continue exploring — recently viewed
    const recents = getRecents().map((s) => state.bySlug.get(s)).filter(Boolean).slice(0, 5);
    if (recents.length) {
      parts.push(`<section class="home-section">${sectionHeadHtml('Continue Exploring')}`);
      parts.push(`<div class="acq-list">${recents.map((e) => acqItemHtml(e, true)).join('')}</div>`);
      parts.push(`</section>`);
    }

    // recently acquired — from repository dates
    const acquired = entries.filter((e) => e.dateAdded).sort((a, b) => b.dateAdded - a.dateAdded).slice(0, 6);
    if (acquired.length) {
      parts.push(`<section class="home-section">${sectionHeadHtml('Recently Acquired')}`);
      parts.push(`<div class="acq-list">${acquired.map((e) => acqItemHtml(e, false)).join('')}</div>`);
      parts.push(`</section>`);
    }
  }

  return parts.join('\n');
}

function acqItemHtml(e, showType) {
  return (
    `<div class="acq-item">` +
    `<span class="acq-date">${esc(fmtDate(e.dateAdded))}</span>` +
    `<a class="acq-title" href="#/entry/${esc(e.slug)}">${esc(e.title)}</a>` +
    (showType ? `<span class="acq-type">${badgeHtml(e.type)}</span>` : '') +
    `</div>`
  );
}

function emptyStateHtml() {
  return (
    `<div class="empty">` +
    `<p class="empty-eyebrow">Knowledge Core</p>` +
    `<h2>Your archive is empty.</h2>` +
    `<p>The system is ready.</p>` +
    `<p>The knowledge isn&rsquo;t.</p>` +
    `<div class="empty-code">` +
    `<span class="ec-comment"># add a Markdown entry, then rebuild the index</span><br>` +
    `knowledge/dfir/windows-event-logs.md<br>` +
    `$ node tools/build-knowledge.js` +
    `</div>` +
    `<a class="empty-link" href="https://github.com/TiaRusky/TiaRusky.github.io/blob/main/knowledge/README.md" target="_blank" rel="noopener noreferrer">How the archive works →</a>` +
    `</div>`
  );
}

function viewAll() {
  const entries = [...state.entries].sort((a, b) => a.title.localeCompare(b.title));
  return (
    `<div class="page-head">` +
    `<p class="page-eyebrow">Archive</p>` +
    `<h1>All Knowledge</h1>` +
    `<p class="page-sub">${entries.length} ${entries.length === 1 ? 'entry' : 'entries'}.</p>` +
    `</div>` +
    `<div class="entry-list">${entries.map(entryItemHtml).join('')}</div>`
  );
}

function viewDomains() {
  const domains = domainEntries();
  return (
    `<div class="page-head">` +
    `<p class="page-eyebrow">Browse</p>` +
    `<h1>Domains</h1>` +
    `<p class="page-sub">${domains.length} ${domains.length === 1 ? 'domain' : 'domains'}.</p>` +
    `</div>` +
    `<div class="domain-grid">${domains.map((d, i) => domainCardHtml(d, i)).join('')}</div>`
  );
}

function viewDomain(slug) {
  const d = domainEntries().find((x) => x.key === slug);
  if (!d) return notFoundHtml('Domain not found', 'No domain matches this path.');
  const sorted = [...d.entries].sort((a, b) => a.title.localeCompare(b.title));
  return (
    `<div class="page-head">` +
    `<nav class="breadcrumb"><a href="#/domains">Domains</a><span class="crumb-sep">/</span><span>${esc(d.name)}</span></nav>` +
    `<p class="page-eyebrow">Domain</p>` +
    `<h1>${esc(d.name)}</h1>` +
    `<p class="page-sub">${sorted.length} ${sorted.length === 1 ? 'entry' : 'entries'}.</p>` +
    `</div>` +
    `<div class="entry-list">${sorted.map(entryItemHtml).join('')}</div>`
  );
}

function viewTopics() {
  const byType = new Map();
  for (const e of state.entries) {
    if (e.type === 'tool') continue;
    if (!byType.has(e.type)) byType.set(e.type, []);
    byType.get(e.type).push(e);
  }
  const order = ['artifact', 'event', 'technique', 'concept', 'topic'];
  const types = [...byType.keys()].sort(
    (a, b) => (order.indexOf(a) === -1 ? 99 : order.indexOf(a)) - (order.indexOf(b) === -1 ? 99 : order.indexOf(b))
  );
  const groups = types
    .map((t) => {
      const list = byType.get(t).sort((a, b) => a.title.localeCompare(b.title));
      return (
        `<div class="type-group">` +
        `<div class="type-group-head"><h2>${esc(t)}</h2><span class="type-count">${list.length}</span></div>` +
        `<div class="entry-list">${list.map(entryItemHtml).join('')}</div>` +
        `</div>`
      );
    })
    .join('');
  return (
    `<div class="page-head">` +
    `<p class="page-eyebrow">Browse</p>` +
    `<h1>Topics</h1>` +
    `<p class="page-sub">Organised by conceptual type.</p>` +
    `</div>` +
    groups
  );
}

function viewTools() {
  const tools = state.entries.filter((e) => e.type === 'tool').sort((a, b) => a.title.localeCompare(b.title));
  return (
    `<div class="page-head">` +
    `<p class="page-eyebrow">Browse</p>` +
    `<h1>Tools</h1>` +
    `<p class="page-sub">${tools.length} ${tools.length === 1 ? 'tool' : 'tools'}.</p>` +
    `</div>` +
    (tools.length ? `<div class="entry-list">${tools.map(entryItemHtml).join('')}</div>` : emptyStateHtml())
  );
}

function viewTag(tag) {
  const tagLow = tag.toLowerCase();
  const matches = state.entries
    .filter((e) => e.tags.some((t) => t.toLowerCase() === tagLow))
    .sort((a, b) => a.title.localeCompare(b.title));
  if (!matches.length) return notFoundHtml('Nothing here', `No entries tagged “${esc(tag)}”.`);
  return (
    `<div class="page-head">` +
    `<p class="page-eyebrow">Tag</p>` +
    `<h1>${esc(tag)}</h1>` +
    `<p class="page-sub">${matches.length} ${matches.length === 1 ? 'entry' : 'entries'}.</p>` +
    `</div>` +
    `<div class="entry-list">${matches.map(entryItemHtml).join('')}</div>`
  );
}

function notFoundHtml(title, sub) {
  return (
    `<div class="error-state">` +
    `<h1>${esc(title)}</h1>` +
    `<p>${esc(sub)}</p>` +
    `<p style="margin-top:1.4rem"><a href="#/">← Back to Knowledge home</a></p>` +
    `</div>`
  );
}

// ---------------------------------------------------------------------------
// Entry view
// ---------------------------------------------------------------------------
function resolveRef(ref) {
  const r = String(ref).trim();
  if (!r) return null;
  if (state.bySlug.has(r)) return r;
  const low = r.toLowerCase();
  const byTitle = state.entries.find((e) => e.title.toLowerCase() === low);
  if (byTitle) return byTitle.slug;
  const s = slugify(r);
  if (state.bySlug.has(s)) return s;
  return null;
}

function computeRelated(entry) {
  const scores = new Map();
  const add = (slug, w) => {
    if (slug === entry.slug) return;
    scores.set(slug, (scores.get(slug) || 0) + w);
  };
  (entry.related || []).forEach((r) => {
    const s = resolveRef(r);
    if (s) add(s, 100);
  });
  (entry.wikilinks || []).forEach((t) => {
    const s = resolveRef(t);
    if (s) add(s, 60);
  });
  (entry.tags || []).forEach((t) => {
    for (const e of state.entries) {
      if (e !== entry && e.tags.includes(t)) add(e.slug, 10);
    }
  });
  for (const e of state.entries) {
    if (e !== entry && e.domain === entry.domain) add(e.slug, 2);
  }
  return [...scores.entries()]
    .map(([slug, w]) => ({ slug, w }))
    .sort((a, b) => b.w - a.w || a.slug.localeCompare(b.slug))
    .slice(0, 6)
    .map((x) => state.bySlug.get(x.slug))
    .filter(Boolean);
}

function quickRefFacts(entry, semBlocks) {
  const facts = [];
  const seen = new Set();
  const add = (label, value) => {
    if (value === undefined || value === null || value === '') return;
    const v = Array.isArray(value) ? value.join(', ') : String(value);
    if (!v) return;
    const key = label.toLowerCase();
    if (seen.has(key)) return;
    seen.add(key);
    facts.push({ label, value: v });
  };
  for (const b of semBlocks) {
    if (b.type === 'artifact' || b.type === 'tool' || b.type === 'event') {
      if (b.fields.location) add('Location', b.fields.location);
      if (b.fields.platform) add('Platform', b.fields.platform);
      if (b.fields.category) add('Category', b.fields.category);
      if (b.fields.id) add('Event ID', b.fields.id);
      if (b.fields.source) add('Source', b.fields.source);
      if (b.fields.version) add('Version', b.fields.version);
      if (b.fields.useful_for) add('Useful for', b.fields.useful_for);
    }
  }
  if (!facts.length && entry.tags.length) add('Tags', entry.tags);
  return facts.slice(0, 6);
}

function viewEntry(slug) {
  const entry = state.bySlug.get(slug);
  if (!entry) return notFoundHtml('Entry not found', `No knowledge entry with slug “${esc(slug)}”.`);

  addRecent(entry.slug);
  document.title = `${entry.title} · Knowledge`;

  const { html, blocks } = renderMarkdown(entry.body, {
    resolveWiki: (t) => resolveRef(t),
  });

  const facts = quickRefFacts(entry, blocks);
  const related = computeRelated(entry);
  const domainSlug = slugify(entry.domain) || 'general';

  const breadcrumb =
    `<nav class="breadcrumb">` +
    `<a href="#/">Home</a><span class="crumb-sep">/</span>` +
    `<a href="#/domain/${esc(domainSlug)}">${esc(entry.domain)}</a><span class="crumb-sep">/</span>` +
    `<span>${esc(entry.title)}</span>` +
    `</nav>`;

  const hero =
    `<header class="entry-hero">` +
    `<div class="entry-hero-top">` +
    `<p class="entry-eyebrow">${esc(entry.domain)} · ${esc(entry.type)}</p>` +
    `<button type="button" id="reading-toggle" class="reading-toggle" aria-pressed="${state.readingPref ? 'true' : 'false'}">` +
    `<span class="reading-toggle-icon" aria-hidden="true">Aa</span><span>Reading mode</span>` +
    `</button>` +
    `</div>` +
    `<h1>${esc(entry.title)}</h1>` +
    (entry.excerpt ? `<p class="entry-excerpt">${esc(entry.excerpt)}</p>` : '') +
    `<div class="entry-meta">${badgeHtml(entry.type)}` +
    entry.tags.map((t) => `<a class="tag-chip" href="#/tag/${esc(slugify(t))}">#${esc(t)}</a>`).join('') +
    `</div>` +
    `</header>`;

  const quickref = facts.length
    ? `<div class="quickref"><p class="quickref-label">Quick Reference</p><dl>` +
      facts.map((f) => `<div class="qr-row"><dt>${esc(f.label)}</dt><dd>${esc(f.value)}</dd></div>`).join('') +
      `</dl></div>`
    : '';

  const relatedHtml = related.length
    ? `<section class="related">` +
      `<div class="related-head"><h2>Related Knowledge</h2><span class="section-rule" aria-hidden="true"></span></div>` +
      `<div class="related-grid">` +
      related.map((r) =>
        `<a class="related-card" href="#/entry/${esc(r.slug)}">` +
        `<p class="rc-title">${esc(r.title)}</p>` +
        `<div class="rc-meta">${badgeHtml(r.type)}<span class="entry-item-domain">${esc(r.domain)}</span></div>` +
        `</a>`
      ).join('') +
      `</div>` +
      `<p class="related-more"><a href="#/domain/${esc(domainSlug)}">More in ${esc(entry.domain)} →</a></p>` +
      `</section>`
    : '';

  return (
    breadcrumb +
    hero +
    quickref +
    `<article id="entry-content" class="article">${html}</article>` +
    relatedHtml
  );
}

// ---------------------------------------------------------------------------
// TOC + scrollspy
// ---------------------------------------------------------------------------
function buildToc() {
  const content = $('#entry-content');
  if (!content) return;
  const headings = [...content.querySelectorAll('h2, h3')];
  const toc = $('#toc');
  if (!toc) return;
  const entrySlug = parseRoute().slug || '';
  const hrefFor = (h) => `#/entry/${esc(entrySlug)}#${esc(h.id)}`;

  toc.innerHTML = headings
    .map((h) => `<a class="${h.tagName === 'H3' ? 'toc-h3' : 'toc-h2'}" href="${hrefFor(h)}">${esc(h.textContent)}</a>`)
    .join('');

  // mobile collapsible contents (visible < 1180px)
  if (headings.length >= 2) {
    const existing = $('.mobile-toc');
    if (existing) existing.remove();
    const details = document.createElement('details');
    details.className = 'mobile-toc';
    details.innerHTML =
      `<summary>Contents</summary><nav>` +
      headings.map((h) => `<a href="${hrefFor(h)}">${esc(h.textContent)}</a>`).join('') +
      `</nav>`;
    content.parentNode.insertBefore(details, content);
  }

  // scrollspy
  const links = [...toc.querySelectorAll('a')];
  let ticking = false;
  const setActive = (link) => {
    for (const l of links) l.classList.toggle('active', l === link);
  };
  const update = () => {
    ticking = false;
    const mark = 90;
    let current = null;
    for (const h of headings) {
      if (h.getBoundingClientRect().top <= mark) current = h;
      else break;
    }
    setActive(current ? links.find((l) => l.hash === '#' + current.id) || null : null);
  };
  const onScroll = () => {
    if (ticking) return;
    ticking = true;
    requestAnimationFrame(update);
  };
  window.addEventListener('scroll', onScroll, { passive: true });

  // smooth in-page navigation without re-rendering the article
  const onTocClick = (e) => {
    const link = e.target.closest('a');
    if (!link) return;
    const id = link.getAttribute('href').split('#').pop();
    const target = document.getElementById(id);
    if (!target) return;
    e.preventDefault();
    target.scrollIntoView({ block: 'start', behavior: prefersReducedMotion() ? 'auto' : 'smooth' });
    history.replaceState(null, '', '#' + link.getAttribute('href'));
    setActive(link);
  };
  toc.addEventListener('click', onTocClick);
  const mobileTocNav = $('.mobile-toc nav');
  if (mobileTocNav) mobileTocNav.addEventListener('click', onTocClick);
  update();
}

// ---------------------------------------------------------------------------
// Command palette
// ---------------------------------------------------------------------------
const paletteEl = $('#palette');
const paletteInput = $('#palette-input');
const paletteResults = $('#palette-results');
let paletteActive = -1;

function openPalette() {
  if (!paletteEl) return;
  paletteEl.hidden = false;
  document.body.style.overflow = 'hidden';
  paletteActive = -1;
  paletteInput.value = '';
  paletteResults.innerHTML = '';
  renderPaletteResults();
  paletteInput.focus();
}

function closePalette() {
  if (!paletteEl) return;
  paletteEl.hidden = true;
  document.body.style.overflow = '';
  const trigger = $('#search-trigger');
  (trigger || document.body).focus({ preventScroll: true });
}

function renderPaletteResults() {
  const q = paletteInput.value.trim();
  const results = q ? runSearch(q) : [...state.entries].sort((a, b) => (b.dateAdded || 0) - (a.dateAdded || 0)).slice(0, 10);

  if (!results.length) {
    paletteResults.innerHTML = `<div class="pr-empty">${q ? 'No results for “' + esc(q) + '”.' : 'The archive is empty.'}</div>`;
    paletteActive = -1;
    return;
  }

  const tokens = q.toLowerCase().split(/\s+/).filter(Boolean);
  paletteResults.innerHTML = results
    .map(
      (e, i) =>
        `<button type="button" class="pr-item${i === paletteActive ? ' active' : ''}" role="option" aria-selected="${i === paletteActive}" data-slug="${esc(e.slug)}">` +
        `<div class="pr-item-top">${badgeHtml(e.type)}<span class="pr-item-title">${highlightTokens(e.title, tokens)}</span></div>` +
        `<div class="pr-item-domain">${esc(e.domain)}</div>` +
        (q ? `<div class="pr-item-snippet">${makeSnippet(e, q)}</div>` : '') +
        `</button>`
    )
    .join('');
}

function paletteMove(dir) {
  const items = [...paletteResults.querySelectorAll('.pr-item')];
  if (!items.length) return;
  paletteActive = (paletteActive + dir + items.length) % items.length;
  items.forEach((el, i) => {
    el.classList.toggle('active', i === paletteActive);
    el.setAttribute('aria-selected', i === paletteActive);
  });
  const active = items[paletteActive];
  if (active) active.scrollIntoView({ block: 'nearest' });
}

function paletteOpenActive() {
  const items = [...paletteResults.querySelectorAll('.pr-item')];
  const el = items[paletteActive >= 0 ? paletteActive : 0];
  if (el) {
    location.hash = '#/entry/' + el.getAttribute('data-slug');
    closePalette();
  }
}

// ---------------------------------------------------------------------------
// Wiki-link previews
// ---------------------------------------------------------------------------
const previewEl = $('#preview');
let lastMouse = { x: 0, y: 0 };

function showPreview(link) {
  const slug = link.getAttribute('data-slug');
  const entry = state.bySlug.get(slug);
  if (!entry) return;
  previewEl.innerHTML =
    `<p class="preview-title">${esc(entry.title)}</p>` +
    `<div class="preview-meta">${badgeHtml(entry.type)}<span class="entry-item-domain">${esc(entry.domain)}</span></div>` +
    (entry.excerpt ? `<p class="preview-excerpt">${esc(entry.excerpt)}</p>` : '') +
    `<p class="preview-open">Open →</p>`;
  previewEl.hidden = false;
  requestAnimationFrame(() => {
    previewEl.classList.add('visible');
    positionPreview(lastMouse.x, lastMouse.y);
  });
}

function hidePreview() {
  previewEl.classList.remove('visible');
  previewEl.hidden = true;
}

function positionPreview(x, y) {
  const rect = previewEl.getBoundingClientRect();
  const pad = 14;
  let left = x + pad;
  if (left + rect.width > window.innerWidth - pad) left = x - rect.width - pad;
  left = Math.max(pad, left);
  let top = y + pad;
  if (top + rect.height > window.innerHeight - pad) top = y - rect.height - pad;
  top = Math.max(pad, top);
  previewEl.style.left = left + 'px';
  previewEl.style.top = top + 'px';
}

// ---------------------------------------------------------------------------
// Copy buttons
// ---------------------------------------------------------------------------
async function copyText(text, btn) {
  try {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(text);
    } else {
      const ta = document.createElement('textarea');
      ta.value = text;
      ta.style.position = 'fixed';
      ta.style.opacity = '0';
      document.body.appendChild(ta);
      ta.select();
      document.execCommand('copy');
      ta.remove();
    }
    btn.classList.add('copied');
    const original = btn.textContent;
    btn.textContent = 'Copied';
    setTimeout(() => {
      btn.classList.remove('copied');
      btn.textContent = original;
    }, 1500);
  } catch {
    btn.textContent = 'Error';
  }
}

// ---------------------------------------------------------------------------
// Rail + shared UI
// ---------------------------------------------------------------------------
function updateRail(route) {
  const counts = {
    all: state.entries.length,
    domains: domainEntries().length,
    topics: state.entries.filter((e) => e.type !== 'tool').length,
    tools: state.entries.filter((e) => e.type === 'tool').length,
  };
  document.querySelectorAll('.rail-link[data-count]').forEach((a) => {
    const key = a.getAttribute('data-count');
    const val = counts[key];
    let label = a.childNodes[0].textContent.trim();
    if (label) a.innerHTML = esc(label) + (val !== undefined ? `<span class="rail-count">${val}</span>` : '');
  });
  document.querySelectorAll('.rail-link').forEach((a) => a.removeAttribute('aria-current'));
  const activeMap = { all: '#/all', domains: '#/domains', topics: '#/topics', tools: '#/tools' };
  const sel = activeMap[route.name];
  if (sel) {
    const link = document.querySelector(`.rail-link[href="${sel}"]`);
    if (link) link.setAttribute('aria-current', 'page');
  }

  // rail recents
  const railRecents = $('#rail-recents');
  if (railRecents) {
    const recents = getRecents().map((s) => state.bySlug.get(s)).filter(Boolean).slice(0, 5);
    railRecents.innerHTML = recents.length
      ? recents.map((e) => `<a class="rail-recent" href="#/entry/${esc(e.slug)}">${esc(e.title)}</a>`).join('')
      : `<p class="rail-recent-empty">Nothing viewed yet.</p>`;
  }
}

function closeRail() {
  const rail = $('#rail');
  const backdrop = $('#rail-backdrop');
  const toggle = $('#rail-toggle');
  rail.classList.remove('open');
  backdrop.classList.remove('show');
  toggle.setAttribute('aria-expanded', 'false');
}

// ---------------------------------------------------------------------------
// Routing / render
// ---------------------------------------------------------------------------
function renderRoute() {
  const route = parseRoute();
  const main = $('#main');
  if (!main) return;

  document.body.classList.toggle('reading', state.readingPref && route.name === 'entry');
  document.body.classList.toggle('has-toc', route.name === 'entry');

  if (!state.loaded && !state.loadError) {
    main.innerHTML = `<div class="empty"><p class="empty-eyebrow">Knowledge Core</p><h2 style="font-family:var(--font-mono);font-size:1rem;color:var(--fg-dim)">LOADING INDEX…</h2></div>`;
    return;
  }
  if (state.loadError) {
    main.innerHTML =
      `<div class="error-state"><h1>Knowledge index unavailable</h1>` +
      `<p>The compiled archive could not be loaded (${esc(state.loadError.message)}).</p>` +
      `<p>Regenerate it from the repository:</p>` +
      `<div class="empty-code">$ node tools/build-knowledge.js</div>` +
      `</div>`;
    return;
  }

  let html = '';
  switch (route.name) {
    case 'entry': html = viewEntry(route.slug); break;
    case 'domain': html = viewDomain(route.slug); break;
    case 'tag': html = viewTag(route.tag); break;
    case 'all': html = viewAll(); break;
    case 'domains': html = viewDomains(); break;
    case 'topics': html = viewTopics(); break;
    case 'tools': html = viewTools(); break;
    default: html = viewHome();
  }

  main.innerHTML = html;

  // per-view hooks
  const toc = $('#toc');
  if (route.name === 'entry') {
    document.title = `${state.bySlug.get(route.slug) ? state.bySlug.get(route.slug).title : 'Entry'} · Knowledge`;
    toc.innerHTML = '';
    buildToc();
    const toggle = $('#reading-toggle');
    if (toggle) {
      toggle.addEventListener('click', () => setReading(!state.readingPref));
    }
  } else {
    toc.innerHTML = '';
  }
  const homeSearch = $('#home-search');
  if (homeSearch) homeSearch.addEventListener('click', openPalette);

  updateRail(route);
  closeRail();
  if (route.anchor) {
    const target = document.getElementById(route.anchor);
    if (target) target.scrollIntoView({ block: 'start' });
  } else {
    window.scrollTo(0, 0);
  }
  main.focus({ preventScroll: true });
}

function setReading(on) {
  state.readingPref = on;
  localStorage.setItem(READING_KEY, on ? '1' : '0');
  const toggle = $('#reading-toggle');
  if (toggle) toggle.setAttribute('aria-pressed', on ? 'true' : 'false');
  document.body.classList.toggle('reading', on && parseRoute().name === 'entry');
}

// ---------------------------------------------------------------------------
// Exit
// ---------------------------------------------------------------------------
function exitApp() {
  // Navigate straight to the shell. history.back() would step through the
  // SPA hash history one entry at a time instead of returning to the terminal.
  window.location.href = '../../index.html';
}

// ---------------------------------------------------------------------------
// Global events
// ---------------------------------------------------------------------------
function bindGlobalEvents() {
  // palette trigger
  const trigger = $('#search-trigger');
  if (trigger) trigger.addEventListener('click', openPalette);

  // palette input
  if (paletteInput) {
    paletteInput.addEventListener('input', () => {
      paletteActive = -1;
      renderPaletteResults();
    });
    paletteInput.addEventListener('keydown', (e) => {
      if (e.key === 'ArrowDown') { e.preventDefault(); paletteMove(1); }
      else if (e.key === 'ArrowUp') { e.preventDefault(); paletteMove(-1); }
      else if (e.key === 'Enter') { e.preventDefault(); paletteOpenActive(); }
      else if (e.key === 'Escape') { e.preventDefault(); closePalette(); }
    });
  }
  if (paletteEl) paletteEl.addEventListener('mousedown', (e) => {
    if (e.target === paletteEl) closePalette();
  });
  if (paletteResults) paletteResults.addEventListener('click', (e) => {
    const item = e.target.closest('.pr-item');
    if (!item) return;
    location.hash = '#/entry/' + item.getAttribute('data-slug');
    closePalette();
  });

  // wiki-link previews
  document.addEventListener('mouseover', (e) => {
    const link = e.target.closest('.wiki-link[data-slug]');
    if (link) showPreview(link);
    else hidePreview();
  });
  document.addEventListener('mousemove', (e) => {
    lastMouse = { x: e.clientX, y: e.clientY };
    if (previewEl && !previewEl.hidden) positionPreview(lastMouse.x, lastMouse.y);
  });
  document.addEventListener('scroll', hidePreview, { capture: true, passive: true });
  window.addEventListener('resize', hidePreview);

  // copy buttons (delegated)
  document.addEventListener('click', (e) => {
    const btn = e.target.closest('.code-copy');
    if (btn) {
      e.preventDefault();
      copyText(btn.getAttribute('data-copy') || '', btn);
    }
  });

  // rail toggle (mobile)
  const railToggle = $('#rail-toggle');
  const backdrop = $('#rail-backdrop');
  if (railToggle) {
    railToggle.addEventListener('click', () => {
      const open = !$('#rail').classList.contains('open');
      $('#rail').classList.toggle('open', open);
      backdrop.classList.toggle('show', open);
      railToggle.setAttribute('aria-expanded', open ? 'true' : 'false');
    });
  }
  if (backdrop) backdrop.addEventListener('click', closeRail);

  // exit
  const exitBtn = $('#exit-btn');
  if (exitBtn) exitBtn.addEventListener('click', exitApp);

  // global keyboard
  document.addEventListener('keydown', (e) => {
    const mod = e.ctrlKey || e.metaKey;
    if (mod && (e.key === 'k' || e.key === 'K')) {
      e.preventDefault();
      openPalette();
      return;
    }
    if (e.key === 'Escape') {
      if (paletteEl && !paletteEl.hidden) { closePalette(); return; }
      if ($('#rail') && $('#rail').classList.contains('open')) { closeRail(); return; }
      exitApp();
      return;
    }
    if (e.key === '/' && !paletteEl.hidden) return;
    const target = e.target;
    const typing = target && (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.isContentEditable);
    if (e.key === '/' && !typing) {
      e.preventDefault();
      openPalette();
    }
  });

  // hash routing
  window.addEventListener('hashchange', renderRoute);
}

// ---------------------------------------------------------------------------
// Init
// ---------------------------------------------------------------------------
async function init() {
  state.readingPref = localStorage.getItem(READING_KEY) === '1';
  bindGlobalEvents();
  await loadIndex();
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', init);
} else {
  init();
}
